// Core SOC Playbook Studio functionality (preserved from Phase 4 source).
const starterPlaybooks=[
{id:'PB-001',name:'Suspicious PowerShell Execution',category:'Endpoint',description:'The monitoring team identified PowerShell execution that may require validation. Review the initiating process, user context, command line, and destination details to determine whether the activity aligns with approved administrative or business operations.',fields:[{key:'HostName',value:'WS-042'},{key:'UserName',value:'j.smith'},{key:'ProcessName',value:'powershell.exe'},{key:'CommandLine',value:'powershell.exe -enc [redacted]'},{key:'EventTime',value:'2026-10-09 08:42:16'}],template:'The monitoring team observed suspicious PowerShell execution on endpoint {{HostName}} at {{EventTime}}. The activity was associated with user {{UserName}}, with process {{ProcessName}} executing the command line: {{CommandLine}}.\n\nThe activity should be validated to confirm whether it was initiated for an approved administrative or business purpose. The provided event details alone do not confirm malicious activity.'},
{id:'PB-002',name:'Account Created and Deleted',category:'Identity',description:'The monitoring team identified an account creation event followed by deletion within a short timeframe. Validate the account lifecycle, the initiating identity, and whether the activity was expected as part of an approved administrative or provisioning workflow.',fields:[{key:'CreatedUser',value:'temp.contractor'},{key:'CreatedByUser',value:'admin.user'},{key:'DeletedByUser',value:'admin.user'},{key:'HostName',value:'AD01.corp.local'},{key:'CreationTime',value:'2026-10-09 09:12:22'},{key:'DeletionTime',value:'2026-10-09 09:24:51'},{key:'TimeDelta',value:'12 minutes 29 seconds'}],template:'The monitoring team observed that the account {{CreatedUser}} was created on {{HostName}} at {{CreationTime}} and subsequently deleted at {{DeletionTime}}, within {{TimeDelta}}. The creation was performed by {{CreatedByUser}}, and the deletion was attributed to {{DeletedByUser}}.\n\nPlease confirm whether this account lifecycle was expected and associated with an approved administrative, contractor onboarding, or testing activity. The sequence alone does not establish malicious intent.'},
{id:'PB-003',name:'Multiple Failed Login Attempts',category:'Identity',description:'The monitoring team observed repeated authentication failures associated with an account or source. Review the attempt volume, source address, target account, and surrounding successful logins to determine whether the activity is expected or requires further validation.',fields:[{key:'UserName',value:'a.lee'},{key:'SourceIP',value:'198.51.100.24'},{key:'HostName',value:'VPN-GW-01'},{key:'FailedAttempts',value:'18'},{key:'FirstSeen',value:'2026-10-09 07:55:02'},{key:'LastSeen',value:'2026-10-09 08:03:47'}],template:'The monitoring team observed {{FailedAttempts}} failed login attempts for user {{UserName}} on {{HostName}} from source IP {{SourceIP}} between {{FirstSeen}} and {{LastSeen}}.\n\nPlease validate whether the source and authentication activity are expected. If the activity is not recognised, review the affected account and confirm whether any successful authentication occurred during or after this period.'},
{id:'PB-004',name:'Malware / PUP Detection',category:'Endpoint',description:'The monitoring team identified an endpoint security detection that requires review. Validate the detection name, file location, endpoint, and action taken by the security product before determining the appropriate remediation.',fields:[{key:'HostName',value:'LAP-118'},{key:'UserName',value:'m.rao'},{key:'DetectionName',value:'Potentially Unwanted Program'},{key:'FilePath',value:'C:\\Users\\m.rao\\Downloads\\tool.exe'},{key:'ActionTaken',value:'Quarantined'},{key:'DetectionTime',value:'2026-10-09 08:18:34'}],template:'The monitoring team observed an endpoint security detection on {{HostName}} at {{DetectionTime}}. The alert, {{DetectionName}}, was associated with user {{UserName}} and the file path {{FilePath}}. The security product reported the action taken as: {{ActionTaken}}.\n\nPlease confirm whether the file and related application are required for business purposes. If not required, remove the application and its associated files in accordance with your endpoint remediation process.'}
];
const STORAGE_KEY='soc-playbook-studio-v1';function loadSavedPlaybooks(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return JSON.parse(JSON.stringify(starterPlaybooks));const data=JSON.parse(raw);if(Array.isArray(data)&&data.every(p=>p&&p.id&&p.name&&p.category&&p.description&&Array.isArray(p.fields)&&typeof p.template==='string'))return data}catch(e){}return JSON.parse(JSON.stringify(starterPlaybooks))}let playbooks=loadSavedPlaybooks();let selectedId=playbooks.some(p=>p.id==='PB-001')?'PB-001':(playbooks[0]?.id||'');let activeFilter='All';let editingId=null;let showAllPlaybooks=false;let toastTimer;function savePlaybooks(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(playbooks))}catch(e){}}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function selected(){return playbooks.find(p=>p.id===selectedId)||playbooks[0]}
function notify(msg){const t=$('toast');t.textContent='';const message=document.createElement('span');message.textContent=msg;const close=document.createElement('button');close.type='button';close.className='toast-close';close.setAttribute('aria-label','Dismiss notification');close.textContent='×';close.onclick=()=>{clearTimeout(toastTimer);t.classList.add('hidden')};t.append(message,close);t.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('hidden'),4200)}
function renderList(){const q=$('playbook-search').value.trim().toLowerCase();const items=playbooks.filter(p=>(activeFilter==='All'||p.category===activeFilter)&&(`${p.name} ${p.description} ${p.category}`.toLowerCase().includes(q)));const compact=!q&&!showAllPlaybooks;const visible=compact?items.slice(0,3):items;if(compact&&selectedId&&!visible.some(p=>p.id===selectedId)){const selectedMatch=items.find(p=>p.id===selectedId);if(selectedMatch)visible.push(selectedMatch)}if(compact&&selectedId&&!visible.some(p=>p.id===selectedId)){const selectedMatch=items.find(p=>p.id===selectedId);if(selectedMatch)visible.push(selectedMatch)}$('playbook-count').textContent=String(playbooks.length).padStart(2,'0')+' templates';$('stat-playbooks').textContent=playbooks.length;$('playbook-list').innerHTML=visible.length?visible.map(p=>`<button class="playbook-item ${p.id===selectedId?'active':''}" data-id="${esc(p.id)}"><div class="pb-title">${esc(p.name)} <span class="tag ${p.id.startsWith('PB-')?'blue':'green'}">${esc(p.category)}</span></div><div class="pb-desc">${esc(p.description.slice(0,104))}${p.description.length>104?'…':''}</div><div class="pb-meta"><span class="tag">${p.fields.length} fields</span><span class="tag">${p.id.startsWith('PB-')?'Built-in':'Custom'}</span></div></button>`).join(''):'<div class="empty">No matching playbooks. Try another search or add a use case.</div>';const more=$('more-playbooks');more.classList.toggle('hidden',items.length<=3||Boolean(q));more.textContent=showAllPlaybooks?'Show fewer playbooks':'Show more playbooks…';more.setAttribute('aria-expanded',String(showAllPlaybooks));document.querySelectorAll('#playbook-list [data-id]').forEach(b=>b.addEventListener('click',()=>selectPlaybook(b.dataset.id)))}
function renderFields(){const p=selected();$('selected-title').textContent=p.name;$('selected-subtitle').textContent=p.category+' · Incident analysis template';$('selected-id').textContent=p.id;$('selected-description').textContent=p.description;$('field-count-label').textContent=p.fields.length+' values';$('stat-fields').textContent=p.fields.length;$('field-rows').innerHTML=p.fields.map((f,i)=>`<div class="field-row"><div class="field-key">${esc(f.key)}<div class="field-hint">Template value</div></div><input class="field-input" data-index="${i}" aria-label="Value for ${esc(f.key)}" value="${esc(f.value)}" placeholder="Enter ${esc(f.key)}…"><button class="remove-field" data-remove="${i}" title="Remove field" aria-label="Remove ${esc(f.key)}">×</button></div>`).join('');document.querySelectorAll('.field-input').forEach(inp=>inp.addEventListener('input',()=>{p.fields[Number(inp.dataset.index)].value=inp.value;renderOutput()}));document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{p.fields.splice(Number(b.dataset.remove),1);renderFields();renderList()}));renderOutput()}
function renderOutput(){const p=selected();let out=p.template;for(const f of p.fields){const token=new RegExp('{{\\s*'+f.key.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+'\\s*}}','g');out=out.replace(token,f.value.trim()||'[Not provided: '+f.key+']')}const recs=Array.isArray(p.recommendations)?p.recommendations:[];if(recs.length)out+='\n\nRecommendations:\n'+recs.map(r=>'• '+String(r).trim()).filter(r=>r!=='•').join('\n');$('generated-output').textContent=out;$('field-count-label').textContent=p.fields.length+' values';$('stat-fields').textContent=p.fields.length}
function selectPlaybook(id){selectedId=id;renderList();renderFields()}
function showPage(page){$('workspace-page').classList.toggle('hidden',page!=='workspace');$('admin-page').classList.toggle('hidden',page!=='admin');$('library-page').classList.toggle('hidden',page!=='library');$('apps-page').classList.toggle('hidden',page!=='apps');$('parser-page').classList.toggle('hidden',page!=='parser');$('crumb-current').textContent=page==='admin'?'Use case builder':page==='library'?'Playbook library':page==='apps'?'Apps':page==='parser'?'Common Log Parser':'Playbook workspace';document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(page==='library')renderLibrary();window.scrollTo({top:0,behavior:'smooth'})}
function resetFields(){const p=selected();p.fields=p.fields.map(f=>({...f,value:''}));renderFields();notify('Field values cleared.')}
function addField(){if(window.SOCStudioAccess&&!window.SOCStudioAccess.isAdmin()){notify('Only an administrator can change playbook field definitions.');return}const key=prompt('Enter a field key (for example, SourceIP):');if(!key||!key.trim())return;const clean=key.trim().replace(/[^\w.-]/g,'');if(!clean){notify('Please use letters, numbers, dots, underscores, or hyphens.');return}if(selected().fields.some(f=>f.key.toLowerCase()===clean.toLowerCase())){notify('That field key already exists.');return}selected().fields.push({key:clean,value:''});renderFields();renderList()}
function openBuilder(){if(window.SOCStudioAccess&&!window.SOCStudioAccess.isAdmin()){notify('Only an administrator can create or edit playbooks.');return}editingId=null;$('usecase-form').reset();$('form-title').textContent='Create a new use case';$('save-usecase').textContent='＋ Save use case';showPage('admin')}
function renderLibrary(){const q=$('library-search').value.toLowerCase();const list=playbooks.filter(p=>(p.name+' '+p.category+' '+p.description).toLowerCase().includes(q));$('library-list').innerHTML=list.length?list.map(p=>`<div class="playbook-item"><div class="pb-title">${esc(p.name)} <span class="tag blue">${esc(p.category)}</span></div><div class="pb-desc">${esc(p.description.slice(0,125))}${p.description.length>125?'…':''}</div><div class="pb-meta"><span class="tag">${p.fields.length} fields</span><span class="tag">${p.id.startsWith('PB-')?'Built-in':'Custom'}</span></div><div class="field-actions"><button class="btn btn-soft" data-open="${esc(p.id)}">Use playbook</button><button class="btn" data-edit="${esc(p.id)}">Edit</button>${!p.id.startsWith('PB-')?`<button class="btn btn-danger" data-delete="${esc(p.id)}">Delete</button>`:''}</div></div>`).join(''):'<div class="empty">No playbooks found.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selectPlaybook(b.dataset.open);showPage('workspace')});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editPlaybook(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deletePlaybook(b.dataset.delete))}
function editPlaybook(id){if(window.SOCStudioAccess&&!window.SOCStudioAccess.isAdmin()){notify('Playbooks are read-only for local users.');return}const p=playbooks.find(x=>x.id===id);if(!p)return;editingId=id;$('form-title').textContent='Edit use case';$('save-usecase').textContent='✓ Update use case';$('uc-name').value=p.name;$('uc-category').value=p.category;$('uc-description').value=p.description;$('uc-fields').value=p.fields.map(f=>f.key).join(', ');$('uc-template').value=p.template;$('uc-recommendations').value=(p.recommendations||[]).join('\n');showPage('admin')}
function deletePlaybook(id){if(window.SOCStudioAccess&&!window.SOCStudioAccess.isAdmin()){notify('Only an administrator can delete playbooks.');return}if(!confirm('Delete this custom playbook? This cannot be undone unless you exported a backup.'))return;playbooks=playbooks.filter(p=>p.id!==id);if(selectedId===id)selectedId=playbooks[0]?.id||'';renderList();if(selected())renderFields();renderLibrary();notify('Custom playbook deleted.')}
$('usecase-form').addEventListener('submit',e=>{e.preventDefault();if(window.SOCStudioAccess&&!window.SOCStudioAccess.isAdmin()){notify('Playbooks are read-only for local users.');return;}const name=$('uc-name').value.trim(),category=$('uc-category').value,description=$('uc-description').value.trim(),keys=[...new Set($('uc-fields').value.split(',').map(s=>s.trim()).filter(Boolean))],template=$('uc-template').value.trim(),recommendations=$('uc-recommendations').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!name||!description||!keys.length||!template){notify('Please complete all required fields.');return}if(keys.some(k=>! /^[\w.-]+$/.test(k))){notify('Field keys should use letters, numbers, dots, underscores, or hyphens.');return}const prior=editingId?playbooks.find(p=>p.id===editingId):null;const p={id:editingId||'CUS-'+Date.now().toString(36).toUpperCase(),name,category,description,fields:keys.map(k=>({key:k,value:prior?.fields.find(f=>f.key===k)?.value||''})),template,recommendations};if(editingId){playbooks=playbooks.map(x=>x.id===editingId?p:x)}else{playbooks.push(p)}selectedId=p.id;editingId=null;renderList();renderFields();$('usecase-form').reset();$('form-title').textContent='Create a new use case';$('save-usecase').textContent='＋ Save use case';showPage('workspace');notify('Use case saved and ready to use.')});
$('clear-form').onclick=()=>{$('usecase-form').reset();editingId=null;$('form-title').textContent='Create a new use case';$('save-usecase').textContent='＋ Save use case'};
$('suggest-app').onclick=()=>notify('Tell me which threat-intelligence app you want to add, and I can add its link here.');
$('new-usecase-top').onclick=openBuilder;$('library-new').onclick=openBuilder;$('back-workspace').onclick=()=>showPage('workspace');$('add-value-field').onclick=addField;$('reset-fields').onclick=resetFields;$('playbook-search').addEventListener('input',()=>{if($('playbook-search').value.trim())showAllPlaybooks=false;renderList()});$('more-playbooks').onclick=()=>{showAllPlaybooks=!showAllPlaybooks;renderList()};$('library-search').addEventListener('input',renderLibrary);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderList()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$('copy-output').onclick=async()=>{const text=$('generated-output').textContent;try{await navigator.clipboard.writeText(text);notify('Analysis copied to clipboard.')}catch(e){const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');notify('Analysis copied to clipboard.')}catch(_){notify('Copy was blocked by this browser. Select and copy the text manually.')}ta.remove()}};
$('download-txt').onclick=()=>{const blob=new Blob([$('generated-output').textContent],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(selected().name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'incident-analysis')+'.txt';a.click();URL.revokeObjectURL(a.href);notify('Text file generated.')};
function exportJSON(){const blob=new Blob([JSON.stringify({format:'SOC Playbook Studio',version:1,playbooks},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='soc-playbooks-backup.json';a.click();URL.revokeObjectURL(a.href);notify('Playbooks exported as JSON.')}
$('export-btn').onclick=exportJSON;$('export-admin').onclick=exportJSON;$('import-btn').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.playbooks)||!data.playbooks.every(p=>p.name&&p.category&&p.description&&Array.isArray(p.fields)&&typeof p.template==='string'))throw new Error('Invalid file');const imported=data.playbooks.map((p,i)=>({...p,id:'IMP-'+Date.now().toString(36)+'-'+i,fields:p.fields.map(f=>({key:String(f.key),value:String(f.value??'')}))}));if(!confirm(`Import ${imported.length} playbooks? They will be added to the current library.`))return;playbooks.push(...imported);selectedId=imported[0]?.id||selectedId;renderList();if(selected())renderFields();notify('Playbooks imported successfully.')}catch(err){notify('Could not import this file. Please select a valid playbook JSON export.')}e.target.value=''};
