const THEME_KEY='soc-playbook-studio-theme';function applyTheme(theme){document.documentElement.dataset.theme=theme;$('theme-btn').textContent=theme==='light'?'☾ Dark theme':'☀ Light theme';localStorage.setItem(THEME_KEY,theme)}
const savedTheme=localStorage.getItem(THEME_KEY)||'dark';document.documentElement.dataset.theme=savedTheme;
const actionBar=document.querySelector('.top-actions');const themeBtn=document.createElement('button');themeBtn.className='icon-btn';themeBtn.id='theme-btn';themeBtn.type='button';themeBtn.onclick=()=>applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light');actionBar.insertBefore(themeBtn,actionBar.firstChild);
const folderBtn=document.createElement('button');folderBtn.className='icon-btn';folderBtn.id='folder-btn';folderBtn.type='button';folderBtn.textContent='▣ Choose storage folder';folderBtn.title='Choose a folder for automatic playbook JSON saving';actionBar.insertBefore(folderBtn,$('export-btn'));
const STORAGE_DB='soc-playbook-studio-storage',STORAGE_HANDLE_KEY='directory-handle',STORAGE_FILE='soc-playbooks.json';let storageDirectoryHandle=null;let folderWriteQueue=Promise.resolve();
function openStorageDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(STORAGE_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('settings');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeDirectoryHandle(handle){const db=await openStorageDB();await new Promise((resolve,reject)=>{const tx=db.transaction('settings','readwrite');tx.objectStore('settings').put(handle,STORAGE_HANDLE_KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getStoredDirectoryHandle(){try{const db=await openStorageDB();const handle=await new Promise((resolve,reject)=>{const req=db.transaction('settings','readonly').objectStore('settings').get(STORAGE_HANDLE_KEY);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return handle||null}catch(e){return null}}
function validPlaybookData(data){const arr=Array.isArray(data)?data:data?.playbooks;return Array.isArray(arr)&&arr.every(p=>p&&p.id&&p.name&&p.category&&p.description&&Array.isArray(p.fields)&&typeof p.template==='string')?arr:null}
async function readFolderPlaybooks(handle){try{const fileHandle=await handle.getFileHandle(STORAGE_FILE);const data=JSON.parse(await (await fileHandle.getFile()).text());return validPlaybookData(data)}catch(e){return null}}
async function writeFolderPlaybooks(){if(!storageDirectoryHandle)return;folderWriteQueue=folderWriteQueue.then(async()=>{try{const permission=await storageDirectoryHandle.queryPermission({mode:'readwrite'});if(permission!=='granted')return;const fileHandle=await storageDirectoryHandle.getFileHandle(STORAGE_FILE,{create:true});const writable=await fileHandle.createWritable();await writable.write(JSON.stringify({format:'SOC Playbook Studio',version:1,playbooks},null,2));await writable.close();folderBtn.textContent='✓ Folder storage active'}catch(e){folderBtn.textContent='⚠ Storage permission needed'}}).catch(()=>{});return folderWriteQueue}
const originalSavePlaybooks=savePlaybooks;savePlaybooks=function(){originalSavePlaybooks();writeFolderPlaybooks()};
async function activateFolder(handle,loadExisting){storageDirectoryHandle=handle;await storeDirectoryHandle(handle);if(loadExisting){const saved=await readFolderPlaybooks(handle);if(saved){playbooks=saved;selectedId=playbooks.some(p=>p.id===selectedId)?selectedId:(playbooks[0]?.id||'');renderList();if(selected())renderFields();renderLibrary()}}await writeFolderPlaybooks();folderBtn.textContent='✓ Folder storage active';notify('Playbooks will save to '+STORAGE_FILE+' in the selected folder.')}
folderBtn.onclick=async()=>{if(!window.showDirectoryPicker){notify('Folder storage needs a recent Chrome or Edge browser. Use Export JSON as a backup.');return}try{const handle=await window.showDirectoryPicker({mode:'readwrite'});const permission=await handle.requestPermission({mode:'readwrite'});if(permission!=='granted'){notify('Folder access was not granted.');return}const saved=await readFolderPlaybooks(handle);if(saved){if(confirm('A playbook file already exists in this folder. Load it and replace the current in-app library? Choose Cancel to keep the current library and save it to this folder.'))await activateFolder(handle,true);else await activateFolder(handle,false)}else await activateFolder(handle,false)}catch(e){if(e.name!=='AbortError')notify('Could not enable folder storage. Check browser permissions.')}};
async function restoreFolderStorage(){const handle=await getStoredDirectoryHandle();if(!handle)return;try{if(await handle.queryPermission({mode:'readwrite'})!=='granted')return;storageDirectoryHandle=handle;const saved=await readFolderPlaybooks(handle);if(saved){playbooks=saved;selectedId=playbooks.some(p=>p.id===selectedId)?selectedId:(playbooks[0]?.id||'');renderList();if(selected())renderFields();renderLibrary();folderBtn.textContent='✓ Folder storage active'}}catch(e){}}
