const storageHelp=document.querySelector('#admin-page .description-box p');if(storageHelp)storageHelp.textContent='When the shared API is configured, playbook definitions are synchronized to the project repository for all devices. Choose a folder only for an optional local backup; it does not synchronize devices. JSON export remains available as a backup.';
document.querySelectorAll('[data-page]').forEach(b=>{if(b.classList.contains('active'))b.setAttribute('aria-current','page')});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));
applyTheme(savedTheme);document.addEventListener('input',()=>savePlaybooks());document.addEventListener('click',()=>savePlaybooks());renderList();renderFields();restoreFolderStorage();

// Phase 2: practical, local-first SOC workflow helpers.
const CASE_KEY='soc-playbook-studio-case-v1';
const CHECK_KEY='soc-playbook-studio-checklist-v1';
const caseFields=['case-id','case-severity','case-source','case-analyst','case-disposition','case-confidence','case-findings','case-next'];
function loadCase(){try{const saved=JSON.parse(localStorage.getItem(CASE_KEY)||'{}');caseFields.forEach(id=>{if(saved[id]!==undefined&&$(id))$(id).value=saved[id]})}catch(e){}}
function saveCase(){const data={};caseFields.forEach(id=>data[id]=$(id).value);try{localStorage.setItem(CASE_KEY,JSON.stringify(data))}catch(e){notify('Could not save case details in this browser.')}}
function caseContext(){const out={};caseFields.forEach(id=>out[id]=$(id).value.trim());return out}
function handoffText(){const c=caseContext(),p=selected(),checks=[...document.querySelectorAll('[data-check]')];const completed=checks.filter(x=>x.checked).map(x=>'[x] '+x.closest('label').innerText.replace(/\s+/g,' ').trim());const pending=checks.filter(x=>!x.checked).map(x=>'[ ] '+x.closest('label').innerText.replace(/\s+/g,' ').trim());return [
'SOC INCIDENT HANDOFF','='.repeat(48),'Generated: '+new Date().toLocaleString('en-IN',{hour12:false}),
'Case / Ticket: '+(c['case-id']||'Not provided'),'Severity: '+(c['case-severity']||'Not assessed'),'Alert source: '+(c['case-source']||'Not provided'),'Analyst: '+(c['case-analyst']||'Not provided'),'Disposition: '+(c['case-disposition']||'Investigating'),'Assessment confidence: '+(c['case-confidence']||'Not assessed'),
'','USE CASE','Name: '+p.name,'Category: '+p.category,'Playbook ID: '+p.id,'','GENERATED ANALYSIS',$('generated-output').textContent.trim()||'No analysis generated.',
'','KEY FINDINGS / ACTIONS',c['case-findings']||'Not provided.','', 'PENDING ACTIONS / NEXT SHIFT',c['case-next']||'Not provided.','', 'CHECKLIST — COMPLETED',completed.length?completed.join('\n'):'None marked complete.','', 'CHECKLIST — STILL OPEN',pending.length?pending.join('\n'):'All checklist items marked complete.','', 'Reminder: validate evidence and follow your organisation\'s incident response procedures.'].join('\n')}
async function copyText(text,success){try{await navigator.clipboard.writeText(text);notify(success)}catch(e){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{if(document.execCommand('copy'))notify(success);else notify('Clipboard access blocked. Please select and copy the text manually.')}catch(_){notify('Clipboard access blocked. Please select and copy the text manually.')}ta.remove()}}
