function findIocs(){const p=selected(),found=new Set();const ipRe=/(?<![\w.])(?:\d{1,3}\.){3}\d{1,3}(?![\w.])/g;const urlRe=/\bhttps?:\/\/[^\s<>'"`]+/gi;const hashRe=/\b(?:[a-f0-9]{32}|[a-f0-9]{40}|[a-f0-9]{64})\b/gi;const domainRe=/\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:com|net|org|io|co|uk|in|ru|cn|info|biz|xyz|top|dev|app|cloud|local)\b/gi;for(const f of p.fields){const v=String(f.value||'');const key=f.key.toLowerCase();if(/ip|domain|url|hash|ioc|indicator|hostname|hostname|destination|source/.test(key)){for(const item of v.split(/[\s,;]+/).map(x=>x.replace(/[),.;]+$/,'')).filter(Boolean)){if(/^(?:\d{1,3}\.){3}\d{1,3}$/.test(item)||/^https?:\/\//i.test(item)||/^[a-f0-9]{32,64}$/i.test(item)||domainRe.test(item)){found.add(item);domainRe.lastIndex=0}}}for(const re of [urlRe,ipRe,hashRe,domainRe]){const matches=v.match(re)||[];matches.forEach(x=>found.add(x.replace(/[),.;]+$/,'')));re.lastIndex=0}}return [...found].filter(x=>x&&x.length<300).sort((a,b)=>a.localeCompare(b))}
