function parserField(e,keys){for(const key of keys){const exact=Object.entries(e.fields||{}).find(([k,v])=>parserNormKey(k)===parserNormKey(key)&&String(v??'').trim()!=='');if(exact)return String(exact[1])}return ''}
function parserEffectiveProfile(){const selected=$('parser-profile')?.value||'auto';if(selected!=='auto')return selected;if(!parserState.events.length)return 'generic';const counts={};parserState.events.forEach(e=>{let p='generic';if(/Email/.test(e.category)||e.fields?.graph_schema)p='email';else if(/Firewall/.test(e.category))p='firewall';else if(/Network Security/.test(e.category))p='network';else if(/Web Application Firewall|Web Proxy/.test(e.category))p='web';else if(/Endpoint/.test(e.category))p='endpoint';else if(/Authentication|Directory Services/.test(e.category))p='auth';else if(/VPN/.test(e.category))p='vpn';else if(/Cloud Audit/.test(e.category))p='cloud';counts[p]=(counts[p]||0)+1});const ranked=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return ranked.length&&ranked[0][1]/parserState.events.length>=.6?ranked[0][0]:'generic'}
function parserOtherFields(e,profile){const def=parserProfileDefinitions[profile]||parserProfileDefinitions.generic;const core=new Set(['timestamp','@timestamp','time','date','eventtime','event_time','event','event_name','eventname','event_type','eventtype','action','category','event_category','log_type','logtype','source_ip','src_ip','srcip','destination_ip','dst_ip','dstip','username','user','user_name','host','hostname','host_name','event_id','eventid']);const items=[];for(const [k,v] of Object.entries(e.fields||{})){if(v==null||String(v).trim()==='')continue;const nk=parserNormKey(k);if(core.has(nk)||/^_packet/.test(k)||/^graph_(message_id|conversation_id|web_link)$/.test(k))continue;if(/^(raw|message)$/i.test(k))continue;items.push(k+': '+String(v).replace(/\s+/g,' ').slice(0,150));}const iocs=parserExtractIocs(e.raw||'').slice(0,8).map(i=>'IOC '+i.type+': '+i.value);const merged=[...items.slice(0,6),...iocs].slice(0,9);return merged.join(' · ')||'—'}
function parserRender(){
 const filtered=parserFilteredEvents(),rawMode=$('parser-view').value==='raw';
 $('parser-stat-input').textContent=parserState.rawRecords.length.toLocaleString('en-IN');$('parser-stat-parsed').textContent=parserState.events.filter(e=>e.parseMode!=='fallback').length.toLocaleString('en-IN');$('parser-stat-iocs').textContent=parserState.iocs.length.toLocaleString('en-IN');
 $('parser-results-caption').textContent=parserState.events.length?`${parserState.events.length.toLocaleString('en-IN')} records processed${parserState.sourceName?' from '+parserState.sourceName:''}`:'Run the parser to see normalized events here.';
 $('parser-showing').textContent=`Showing ${filtered.length.toLocaleString('en-IN')} of ${parserState.events.length.toLocaleString('en-IN')} events`;
 $('parser-copy-json').disabled=!filtered.length;$('parser-download-json').disabled=!filtered.length;$('parser-download-csv').disabled=!filtered.length;$('parser-copy-iocs').disabled=!parserState.iocs.length;
 $('parser-table-wrap').classList.toggle('hidden',rawMode);$('parser-raw-view').classList.toggle('hidden',!rawMode);
 if(rawMode){$('parser-raw-view').textContent=filtered.map(e=>`[${e.index}] ${e.raw}`).join('\n')||'No matching raw records.'}
 else {const profile=parserEffectiveProfile(),def=parserProfileDefinitions[profile]||parserProfileDefinitions.generic;const cols=[['Time',e=>e.time],['Category',e=>e.category],['Event / activity',e=>e.event],...def.columns,['Other fields / IOC',e=>parserOtherFields(e,profile)]];$('parser-table-head').innerHTML='<tr>'+cols.map(c=>'<th>'+parserEscapeCell(c[0])+'</th>').join('')+'</tr>';$('parser-profile-help').textContent=($('parser-profile').value==='auto'?'Auto-detected profile: '+def.label+'. ':'Selected profile: '+def.label+'. ')+def.description;const colCount=cols.length;$('parser-table-body').innerHTML=filtered.length?filtered.map(e=>'<tr>'+cols.map((c,i)=>{const value=c[1](e);return '<td'+(String(value??'').length>90?' title="'+parserEscapeCell(value)+'"':'')+'>'+parserEscapeCell(value||'—')+'</td>'}).join('')+'</tr>').join(''):'<tr><td colspan="'+colCount+'" class="parser-empty">No events match these filters.</td></tr>'}
 $('parser-ioc-list').innerHTML=parserState.iocs.length?parserState.iocs.map(i=>`<span class="parser-ioc-chip"><small>${parserEscapeCell(i.type)}</small>${parserEscapeCell(i.value)}</span>`).join(''):'No indicators extracted yet.';
}
function parserRun(){
 const input=$('log-input').value;const records=parserSplitInput(input);
 $('parser-error').classList.add('hidden');$('parser-error').textContent='';
 if(!records.length){parserState.events=[];parserState.rawRecords=[];parserState.iocs=[];parserRender();$('parser-error').textContent='Paste log entries or load a TXT, LOG, or JSON file first.';$('parser-error').classList.remove('hidden');return}
 parserState.rawRecords=records;parserState.events=records.map((raw,i)=>parserParseRecord(raw,i)).filter(Boolean);parserState.iocs=parserExtractIocs(records.join('\n'));parserState.sourceName=$('log-file-input').files?.[0]?.name||'';
 parserRender();notify(`Parsed ${parserState.events.length} log record(s). Review normalized fields before drawing conclusions.`);
}
function parserDownload(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parserCsvCell(value){const str=String(value??'');return '"'+str.replace(/"/g,'""')+'"'}
function parserCsv(events){const keys=['index','time','category','event','azuredevicename','azuredeviceid','azureos','azurebrowser','azurecompliant','azuremanaged','azuresession','azureuseragent','azureauthmethod','azurerequesttype','azureresultdetail','azureactorid','azureerrornumber','azurelogonerror','azureresultstatus','azureworkload','azureappid','azurerecordtype','srcip','dstip','srcport','dstport','protocol','user','host','eventid','action','severity','process','parentprocess','commandline','service','ticketoptions','port','bytessent','bytesreceived','packetid','collector','packetstart','packetend','hash','httpmethod','httpuri','httpstatus','useragent','threattype','confidence','cloudprovider','subscription','resourcegroup','emailsender','emailrecipient','emailsubject','emaildisplayname','emailto','emailcc','emailbcc','emailreplyto','senttime','receivedtime','createdtime','modifiedtime','internetmessageid','messageid','conversationid','importance','isread','isdraft','hasattachments','classification','flagstatus','emailcategories','emailwebLink','toCount','ccCount','bccCount','parseMode','raw'];return [keys.map(parserCsvCell).join(','),...events.map(e=>keys.map(k=>parserCsvCell(e[k])).join(','))].join('\r\n')}
$('parse-logs').addEventListener('click',parserRun);
$('parser-sample').addEventListener('click',()=>{$('log-input').value=parserSample+'\n'+parserIdentitySamples;$('log-file-name').textContent='Sample data loaded (including email and Azure AD activity)';$('log-file-input').value='';parserState.sourceName='Sample data';parserRun();parserState.sourceName='Sample data';parserRender()});
$('parser-clear').addEventListener('click',()=>{$('log-input').value='';$('log-file-input').value='';$('log-file-name').textContent='No file selected';parserState.events=[];parserState.rawRecords=[];parserState.iocs=[];parserState.sourceName='';$('parser-error').classList.add('hidden');parserRender()});
$('log-file-input').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!/\.(txt|log|json)$/i.test(file.name)){notify('Choose a TXT, LOG, or JSON file.');e.target.value='';return}if(file.size>15*1024*1024){notify('For browser responsiveness, choose a file smaller than 15 MB.');e.target.value='';return}try{$('log-input').value=await file.text();$('log-file-name').textContent=`${file.name} · ${(file.size/1024).toFixed(1)} KB`;parserState.sourceName=file.name;parserRun()}catch(err){notify('Could not read that local file. Try another file.')}});
$('parser-search').addEventListener('input',parserRender);$('parser-category').addEventListener('change',parserRender);$('parser-view').addEventListener('change',parserRender);$('parser-profile').addEventListener('change',parserRender);
$('parser-copy-json').addEventListener('click',()=>{const events=parserFilteredEvents();copyText(JSON.stringify(events.map(({fields,raw,...e})=>({...e,fields,raw})),null,2),'Filtered parsed events copied as JSON.')});
$('parser-download-json').addEventListener('click',()=>parserDownload('soc-parsed-logs.json',JSON.stringify(parserFilteredEvents(),null,2),'application/json;charset=utf-8'));
$('parser-download-csv').addEventListener('click',()=>parserDownload('soc-parsed-logs.csv',parserCsv(parserFilteredEvents()),'text/csv;charset=utf-8'));
$('parser-copy-iocs').addEventListener('click',()=>copyText(parserState.iocs.map(i=>i.value).join('\n'),'Likely indicators copied. Validate them before use.'));

caseFields.forEach(id=>$(id).addEventListener('input',saveCase));caseFields.filter(id=>$(id).tagName==='SELECT').forEach(id=>$(id).addEventListener('change',saveCase));
$('copy-handoff').onclick=()=>copyText(handoffText(),'Incident handoff note copied.');$('download-handoff').onclick=()=>downloadText(handoffText(),'soc-incident-handoff.txt');$('clear-case').onclick=()=>{if(!confirm('Clear the incident context fields saved in this browser?'))return;caseFields.forEach(id=>$(id).value='');saveCase();notify('Incident context cleared.')};
document.querySelectorAll('[data-check]').forEach(b=>b.addEventListener('change',updateChecklist));$('reset-checklist').onclick=()=>{document.querySelectorAll('[data-check]').forEach(b=>b.checked=false);updateChecklist();notify('Investigation checklist reset.')};$('copy-checklist').onclick=()=>{const boxes=[...document.querySelectorAll('[data-check]')];copyText(boxes.map(b=>(b.checked?'[x] ':'[ ] ')+b.closest('label').innerText.replace(/\s+/g,' ').trim()).join('\n'),'Checklist status copied.')};
$('refresh-iocs').onclick=()=>{const iocs=updateIocs();notify(iocs.length?iocs.length+' likely indicator(s) detected.':'No likely indicators detected.')};$('copy-iocs').onclick=()=>{const iocs=updateIocs();if(!iocs.length){notify('No indicators to copy yet.');return}copyText(iocs.join('\n'),'IOC list copied. Review it before using external tools.')};$('open-ioc-scanner').onclick=()=>{const win=window.open('https://bulkiocscanner.onrender.com/','_blank');if(!win){notify('Pop-up blocked. Open https://bulkiocscanner.onrender.com/ in a new tab.');return}try{win.opener=null}catch(e){}notify('Bulk IOC Scanner opened. Paste indicators manually; no data was sent automatically.')};
const phase2RenderFields=renderFields;renderFields=function(){phase2RenderFields();updateIocs()};
try{loadCase();const savedChecks=JSON.parse(localStorage.getItem(CHECK_KEY)||'[]');document.querySelectorAll('[data-check]').forEach(b=>b.checked=savedChecks.includes(b.dataset.check));updateChecklist();updateIocs()}catch(e){}
